def swap(pair):
    a, b = pair
    return (b, a)

def min_max(nums):
    lo = hi = nums[0]
    for n in nums[1:]:
        if n < lo:
            lo = n
        if n > hi:
            hi = n
    return (lo, hi)

def unzip(pairs):
    firsts = []
    seconds = []
    for a, b in pairs:
        firsts.append(a)
        seconds.append(b)
    return (firsts, seconds)
